<?php $summary=rating_summary((int)$listing['id']);$tags=array_filter(array_map('trim',explode(',',(string)$listing['tags'])));$returnTo=ltrim($_SERVER['REQUEST_URI']??'index.php','/');?>
<article class="listing-card lg4-listing-card" data-reveal="up"><a class="listing-image" href="<?= app_path('index.php?listing='.rawurlencode($listing['slug'])) ?>"><img src="<?= h(listing_image($listing)) ?>" alt="<?= h($listing['name']) ?>" loading="lazy" onerror="this.src='<?= h(app_path('assets/img/place-placeholder.svg')) ?>'"><?php if((int)$listing['featured']): ?><span class="image-badge"><i class="fa-solid fa-sparkles"></i> Featured</span><?php endif; ?><?php if((int)($listing['sponsored']??0)): ?><span class="sponsored-badge">Sponsored</span><?php endif; ?><?php if((int)$listing['is_demo']): ?><span class="sample-badge">Sample</span><?php endif; ?></a><div class="listing-card-body"><div class="listing-meta"><span class="category-label"><?= h($listing['category']) ?></span><?php if($summary['count']): ?><span class="rating"><i class="fa-solid fa-star"></i> <?= h((string)$summary['average']) ?> <small>(<?= $summary['count'] ?>)</small></span><?php else: ?><span class="rating muted-rating">New</span><?php endif; ?></div><h3><a href="<?= app_path('index.php?listing='.rawurlencode($listing['slug'])) ?>"><?= h($listing['name']) ?></a><?php if((int)($listing['verified']??0)): ?> <span class="verified-mark" title="Business details reviewed"><i class="fa-solid fa-circle-check"></i></span><?php endif; ?></h3><p class="listing-location"><i class="fa-solid fa-location-dot"></i> <?= h($listing['location']) ?><?= !empty($listing['city'])?' · '.h($listing['city']):'' ?></p><p class="listing-description"><?= h(text_excerpt((string)$listing['description'],128,'…')) ?></p><?php if($tags): ?><div class="tag-row"><?php foreach(array_slice($tags,0,3) as $tag): ?><span><?= h($tag) ?></span><?php endforeach; ?></div><?php endif; ?><div class="card-bottom"><a class="text-link" href="<?= app_path('index.php?listing='.rawurlencode($listing['slug'])) ?>">Explore details <i class="fa-solid fa-arrow-right"></i></a><div class="card-quick-actions"><label class="compare-toggle"><input type="checkbox" data-compare-id="<?= (int)$listing['id'] ?>" data-compare-name="<?= h($listing['name']) ?>"><span>Compare</span></label><?php if(!empty($listing['whatsapp'])): ?><a class="round-link" href="https://wa.me/<?= h(preg_replace('/\D/','',$listing['whatsapp'])) ?>?text=<?= rawurlencode('Hi, I saw your business '.$listing['name'].' on LocalGuide.') ?>" target="_blank" rel="noopener" aria-label="WhatsApp" title="Chat on WhatsApp" style="color:#25D366;"><i class="fa-brands fa-whatsapp"></i></a><?php endif; ?><a class="round-link" href="<?= h(map_url($listing)) ?>" aria-label="Get directions (sign-in required for guests)" title="Get directions"><i class="fa-solid fa-diamond-turn-right"></i></a><?php if(current_user()): ?><form method="post" action="<?= app_path('favorite.php') ?>"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$listing['id'] ?>"><input type="hidden" name="return_to" value="<?= h($returnTo) ?>"><button class="round-link favorite-control <?= is_favorite((int)$listing['id'])?'is-favorite':'' ?>" aria-label="Toggle favourite"><i class="fa-<?= is_favorite((int)$listing['id'])?'solid':'regular' ?> fa-heart"></i></button></form><?php endif; ?></div></div></div></article>
